import itertools
n=10
# Backtracking with pruning differences
used=[False]*n
perm=[]
# diffs[d] set of row diffs for col difference d
sets=[set() for _ in range(n)]

def bt(c):
    if c==n:
        return perm.copy()
    # try values maybe
    for r in range(n):
        if used[r]: continue
        ok=True
        new=[]
        for i,ri in enumerate(perm):
            d=c-i
            diff=r-ri
            if diff in sets[d]:
                ok=False; break
            new.append((d,diff))
        if not ok: continue
        perm.append(r); used[r]=True
        for d,diff in new: sets[d].add(diff)
        res=bt(c+1)
        if res: return res
        for d,diff in new: sets[d].remove(diff)
        used[r]=False; perm.pop()
    return None
res=bt(0)
print(res)
# verify
if res:
    seen=set()
    for i in range(n):
        for j in range(i+1,n):
            v=(res[j]-res[i], j-i)
            if v in seen: print('dup', v)
            seen.add(v)
    print(len(seen))
